// ============================================================
// RADAR DE REFERÊNCIAS: o que pesquisar por marca.
// Troque os PREENCHER. Alvos que começam com PREENCHER são ignorados (o fluxo roda sem quebrar).
// ig_user_id: o mesmo do fluxo principal (id da conta Business de cada marca).
// ============================================================
const ano = String($now.setZone('America/Sao_Paulo').year);
const MARCAS = [
  {
    marca_id: 'tabua', nome: 'Tábua', ig_user_id: 'PREENCHER_IG_USER_ID_TABUA',
    modelos: ['comanda', 'antes_depois', 'carrossel', 'dica', 'anuncio', 'tela_cardapio', 'enquete', 'foto_titulo', 'novidade', 'carrossel_continuo'],
    perfis: ['goomer_br', 'cardapio.web', 'olaclickbrasil', 'instadelivery.com.br'], // concorrentes diretos (cardápio digital), confirmados
    adjacentes: ['menudinobr'], // plataforma de delivery: outro segmento, só referência de linguagem com o dono de restaurante
    hashtags: ['cardapiodigital', 'donoderestaurante', 'gestaoderestaurante'],
    consultas: [
      `conteúdo Instagram restaurantes e bares tendências ${ano}`,
      `cardápio digital novidades recursos plataformas Brasil ${ano}`,
      `o que donos de restaurante mais pesquisam delivery próprio comissão ${ano}`,
    ],
  },
  {
    marca_id: 'puka', nome: 'Puka', ig_user_id: 'PREENCHER_IG_USER_ID_PUKA',
    modelos: ['titulo', 'lista', 'numero', 'foto'],
    perfis: ['PREENCHER_CONCORRENTE_1', 'PREENCHER_CONCORRENTE_2', 'PREENCHER_CONCORRENTE_3', 'PREENCHER_MARCA_SIMILAR_1'],
    hashtags: ['atendimentowhatsapp', 'crm', 'whatsappbusiness'],
    consultas: [
      `conteúdo Instagram CRM e atendimento WhatsApp tendências ${ano}`,
      `CRM com IA no WhatsApp novidades recursos plataformas Brasil ${ano}`,
      `o que donos de academias e clínicas mais pesquisam sobre atendimento ${ano}`,
    ],
  },
  {
    marca_id: 'ezf', nome: 'ezf.tech', ig_user_id: 'PREENCHER_IG_USER_ID_EZF',
    modelos: ['titulo', 'lista', 'numero', 'foto'],
    perfis: ['PREENCHER_CONCORRENTE_1', 'PREENCHER_CONCORRENTE_2', 'PREENCHER_MARCA_SIMILAR_1'],
    hashtags: ['sitesprofissionais', 'automacaowhatsapp', 'pequenasempresas'],
    consultas: [
      `conteúdo Instagram desenvolvedor freelancer sites e automação para negócios locais ${ano}`,
      `pequenas empresas site próprio automação WhatsApp tendências ${ano}`,
    ],
  },
];

const ok = (v) => v && !String(v).startsWith('PREENCHER');
const itens = [];
for (const m of MARCAS) {
  const base = { marca_id: m.marca_id, nome: m.nome, ig_user_id: m.ig_user_id, modelos: m.modelos };
  for (const p of m.perfis) if (ok(p) && ok(m.ig_user_id)) itens.push({ json: { ...base, tipo: 'perfil', grupo: 'direto', alvo: String(p).replace(/^@/, '') } });
  for (const p of (m.adjacentes || [])) if (ok(p) && ok(m.ig_user_id)) itens.push({ json: { ...base, tipo: 'perfil', grupo: 'adjacente', alvo: String(p).replace(/^@/, '') } });
  for (const h of m.hashtags) if (ok(m.ig_user_id)) itens.push({ json: { ...base, tipo: 'hashtag', alvo: h } });
  for (const q of m.consultas) itens.push({ json: { ...base, tipo: 'web', alvo: q, consulta: q } });
}
return itens;

// Normaliza o retorno do Business Discovery (ou o erro: conta pessoal, inexistente, limite).
const ctx = $('Alvos do radar').item.json;
const j = $input.item.json || {};
const bd = j.business_discovery;
if (!bd) {
  return { json: { marca_id: ctx.marca_id, fonte: 'perfil', grupo: ctx.grupo, alvo: ctx.alvo, erro: String(j.message || j.error?.message || 'sem dados (conta pessoal ou não encontrada)').slice(0, 200), posts: [] } };
}
const seguidores = Number(bd.followers_count) || 0;
const posts = (bd.media?.data || []).map((p) => ({
  tipo: p.media_type, // IMAGE | VIDEO | CAROUSEL_ALBUM
  data: p.timestamp,
  link: p.permalink,
  legenda: String(p.caption || '').replace(/\s+/g, ' ').slice(0, 400),
  curtidas: p.like_count ?? null, // vem vazio quando o perfil esconde curtidas
  comentarios: Number(p.comments_count) || 0,
}));
return { json: { marca_id: ctx.marca_id, fonte: 'perfil', grupo: ctx.grupo, alvo: ctx.alvo, seguidores, total_posts: Number(bd.media_count) || 0, posts } };

const ctx = $('Alvos do radar').item.json;
const j = $input.item.json || {};
const lista = Array.isArray(j.data) ? j.data : [];
if (!lista.length) return { json: { marca_id: ctx.marca_id, fonte: 'hashtag', alvo: '#' + ctx.alvo, erro: String(j.message || j.error?.message || 'sem posts').slice(0, 200), posts: [] } };
const posts = lista.map((p) => ({
  tipo: p.media_type, data: p.timestamp, link: p.permalink,
  legenda: String(p.caption || '').replace(/\s+/g, ' ').slice(0, 400),
  curtidas: p.like_count ?? null, comentarios: Number(p.comments_count) || 0,
}));
return { json: { marca_id: ctx.marca_id, fonte: 'hashtag', alvo: '#' + ctx.alvo, posts } };

const ctx = $('Alvos do radar').item.json;
const j = $input.item.json || {};
const cand = (j.candidates || [])[0] || {};
const resumo = ((cand.content || {}).parts || []).map((p) => p.text || '').join('\n').replace(/\s+/g, ' ').trim();
const fontes = ((cand.groundingMetadata || {}).groundingChunks || []).map((c) => c.web).filter((x) => x && x.uri);
const vistos = new Set();
const unicas = fontes.filter((f) => (vistos.has(f.uri) ? false : vistos.add(f.uri)));
const resultados = unicas.slice(0, 8).map((f, i) => ({ titulo: f.title || f.uri, url: f.uri, data: '', trecho: i === 0 ? resumo.slice(0, 1500) : '(ver resumo na 1ª fonte)' }));
if (!resultados.length && resumo) resultados.push({ titulo: 'Resumo da busca (sem fontes)', url: '', data: '', trecho: resumo.slice(0, 1500) });
return { json: { marca_id: ctx.marca_id, fonte: 'web', alvo: ctx.alvo, erro: resultados.length ? undefined : (j.error && j.error.message) || 'sem resultados', resultados } };

// Agrupa por marca, calcula engajamento por post e monta o texto que o analista vai ler.
const MARCAS = {};
for (const it of $input.all()) {
  const d = it.json; if (!d.marca_id) continue;
  (MARCAS[d.marca_id] ||= []).push(d);
}
const semana = $now.setZone('America/Sao_Paulo').toFormat("kkkk-'S'WW");
const out = [];
for (const [marca_id, coletas] of Object.entries(MARCAS)) {
  const posts = [];
  const web = [];
  const erros = [];
  for (const c of coletas) {
    if (c.erro) erros.push(`${c.fonte}:${c.alvo} (${c.erro})`);
    if (c.fonte === 'web') web.push(...(c.resultados || []).map((r) => ({ ...r, consulta: c.alvo })));
    else for (const p of c.posts || []) {
      const interacoes = (p.curtidas ?? 0) + p.comentarios;
      // engajamento relativo ao tamanho do perfil; em hashtag não há perfil, então vale a interação bruta
      const taxa = c.seguidores ? (interacoes / c.seguidores) * 100 : null;
      posts.push({ origem: c.fonte === 'perfil' ? '@' + c.alvo + ' (' + (c.grupo || 'direto') + ')' : c.alvo, fonte: c.fonte, grupo: c.grupo || null, ...p, interacoes, taxa: taxa === null ? null : Math.round(taxa * 100) / 100, curtidas_ocultas: p.curtidas === null });
    }
  }
  const nota = (p) => (p.taxa !== null ? p.taxa : p.interacoes / 100);
  const top = [...posts].sort((a, b) => nota(b) - nota(a)).slice(0, 15);
  const mix = {};
  for (const p of top) mix[p.tipo] = (mix[p.tipo] || 0) + 1;
  const linhas = top.map((p, i) => `${i + 1}. [${p.origem} · ${p.tipo} · ${String(p.data || '').slice(0, 10)}] ${p.taxa !== null ? 'engaj. ' + p.taxa + '% · ' : ''}${p.interacoes} interações${p.curtidas_ocultas ? ' (curtidas ocultas)' : ''}\n   ${p.legenda}\n   ${p.link}`).join('\n');
  const linhasWeb = web.slice(0, 20).map((r, i) => `${i + 1}. ${r.titulo} (${r.data || 'sem data'})\n   ${r.url}\n   ${r.trecho}`).join('\n');
  out.push({ json: {
    marca_id, semana, total_posts_analisados: posts.length, total_web: web.length, erros,
    mix_formatos_top: JSON.stringify(mix),
    texto_posts: linhas || '(nenhum post coletado: confira os perfis e o token)',
    texto_web: linhasWeb || '(nenhum resultado de busca)',
    urls_validas: [...top.map((p) => p.link), ...web.map((r) => r.url)].filter(Boolean),
  } });
}
return out;

parameters.text:
=MARCA: {{ $json.marca_id }}
SEMANA: {{ $json.semana }}
MODELOS DISPONÍVEIS: {{ ($('Alvos do radar').all().find((i) => i.json.marca_id === $json.marca_id)?.json.modelos || []).join(', ') }}
FORMATOS NO TOPO DO ENGAJAMENTO: {{ $json.mix_formatos_top }}
COLETAS COM ERRO: {{ ($json.erros || []).join(' | ') || 'nenhuma' }}

POSTS DE REFERÊNCIA (ordenados por engajamento):
{{ $json.texto_posts }}

BUSCA NA WEB:
{{ $json.texto_web }}

