  "type": "object",
  "properties": {
    "resumo": {
      "type": "string",
      "description": "3 a 5 frases: o que está funcionando no segmento esta semana"
    },
    "padroes": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "padrao": {
            "type": "string"
          },
          "formato": {
            "type": "string"
          },
          "por_que_funciona": {
            "type": "string"
          },
          "exemplo_url": {
            "type": "string"
          }
        },
        "required": [
          "padrao",
          "por_que_funciona"
        ]
      }
    },
    "ganchos": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Estruturas de gancho observadas, reescritas sem copiar"
    },
    "lacunas": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "ideias": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "titulo": {
            "type": "string"
          },
          "angulo": {
            "type": "string"
          },
          "modelo": {
            "type": "string"
          },
          "formato": {
            "type": "string",
            "enum": [
              "feed",
              "carrossel",
              "reel",
              "story"
            ]
          },
