            "type": "string",
            "description": "URL da referência (só para consulta interna)"
          },
          "observacao": {
            "type": "string"
          }
        },
        "required": [
          "titulo",
          "angulo",
          "modelo",
          "formato"
        ]
      }
    },
    "alertas": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "resumo",
    "padroes",
    "lacunas",
    "ideias",
    "alertas"
  ]
}

